with latest_match as (select s.id, s.supplier_name, s.country, s.city, s.rating, latest.product_cost from suppliers s left join lateral (select c.cost as product_cost from products c where c.supplier_id = s.id order by c.price desc, c.id desc limit 1) latest on true), ranked as (select * from (select *, row_number() over (partition by city, country order by rating desc, id) as dedup_rank from latest_match) x where dedup_rank = 1), eligible as (select s.* from ranked s where not exists (select 1 from products ch where ch.supplier_id = s.id and month(ch.launch_date) in (1, 3, 5))), with_windows as (select id, supplier_name, country, city, rating, lead(product_cost) over w_hist next_product_cost, lag(product_cost) over w_hist prev_product_cost, lag(rating) over w_hist prev_rating, lead(rating) over w_hist next_rating, row_number() over w_hist row_seq, ntile(10) over (partition by country order by product_cost, id) product_cost_bucket from eligible window w_hist as (partition by country, city order by product_cost, id)), with_last as (select s.id, s.supplier_name, s.city, s.rating, s.prev_product_cost, s.prev_rating, s.next_rating, s.row_seq, s.product_cost_bucket, x.product_launch_date, x.stock_qty from with_windows s left join lateral (select c.launch_date as product_launch_date, c.stock_qty from products c where c.supplier_id = s.id order by c.cost desc, c.id desc limit 1) x on true) select id, city, next_rating, row_seq, product_cost_bucket, stock_qty, max(row_seq) over (partition by city order by product_cost_bucket, id rows between 2 preceding and current row) last3_max_row_seq, avg(row_seq) over (partition by city order by product_cost_bucket, id rows between 2 preceding and current row) last3_avg_row_seq, min(row_seq) over (partition by city order by product_cost_bucket, id rows between 2 preceding and current row) last3_min_row_seq from with_last;
